def check_inclusion(s1, s2):
    from collections import Counter
    need = Counter(s1)
    k = len(s1)
    for start in range(len(s2) - k + 1):
        window = Counter(s2[start:start + k])                            # rebuild the letter counts for this window from scratch
        if window == need:
            return True
    return False


if __name__ == "__main__":
    print(check_inclusion("ab", "eidbaooo"))

