    if k > len(s2):
        return False
    need = [0] * 26
    window = [0] * 26
    for c in s1:
        need[ord(c) - ord('a')] += 1
    for i in range(len(s2)):
        window[ord(s2[i]) - ord('a')] += 1                                # add the entering character
        if i >= k:
            window[ord(s2[i - k]) - ord('a')] -= 1                          # remove the character leaving the window
        if i >= k - 1 and window == need:                                   # window is full size AND letter counts match exactly
            return True
    return False


